import{_ as l,l as i,o as e,c as n,v as o,p as s,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"目标误泛化","description":"","frontmatter":{"title":"目标误泛化","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/goal-misgeneralization.md","filePath":"llm/goal-misgeneralization.md","lastUpdated":1789023840000}'),E={name:"llm/goal-misgeneralization.md"};function c(m,a,g,_,B,A){const t=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="目标误泛化" tabindex="-1">目标误泛化 <a class="header-anchor" href="#目标误泛化" aria-label="Permalink to &quot;目标误泛化&quot;">​</a></h1><div class="epigraph"><p>训练分布上，两条目标叠在一起；出了分布，模型抓住的是相关物，不是你以为写下的那个。</p><footer>—— Shah, Langosco 等，Goal Misgeneralization</footer></div><p><a href="/llm/specification-gaming">上一课</a>把规约本身写错叫做博弈。本课补的缺口是：规约在训练集上<strong>碰巧</strong>与意图一致，换环境后分叉——目标误泛化（goal misgeneralization）。能力已经泛化了，目标没有。后课欺骗性对齐默认你会「训练时看起来对齐」可以来自相关物，而不必来自谋划。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>规约博弈假定 \\(r\\) 与 \\(R^*\\) 在训练支持上已经不一致。误泛化假定：在训练支持上，\\(\\arg\\max r \\approx \\arg\\max R^*\\)，于是检查点、损失、抽检都说「好了」。部署分布一移——新工具、新用户、新激励——代理继续优化的是训练时的<strong>相关物</strong>（「拿硬币」而不是「到终点」、「让评委喜欢」而不是「答对」）。</p><p>语言模型上的相关物包括：模仿标注员语气、避免被红队抓住的表面拒绝、在数学题上写长 CoT 因为长与对相关。训练分布里这些相关物够用；竞赛题、对抗用户、分布外工具调用上，相关物会把行为带走。</p><p><span class="marginnote">Langosco 等人在网格世界里演示：训练时「去Cheese」与「向右上」不可分；测试把 Cheese 挪走，代理仍向右上。这不是能力没学会导航，是目标抓住了错误特征。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>要分离「能力泛化」与「目标泛化」，需要<strong>刻意打破相关</strong>的测试环境：同一能力，相关物与意图反号。例子：训练时正确解总是更长，测试时正确解更短；训练时拒答与无害相关，测试时必须回答的无害请求。若能力指标仍高、意图指标塌，就是误泛化，不是欠拟合。</p><p>训练侧只能推迟：多样化相关物、加对抗比较、把 \\(R^*\\) 的可观察切片写进持有集。不能靠「再多一点同分布数据」保证目标在新相关结构上还在。</p>',10)),(e(),s(h,null,{default:r(()=>[p(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TR%5B%22%E8%AE%AD%E7%BB%83%E6%94%AF%E6%8C%81%EF%BC%9Ar%20%E4%B8%8E%20R*%20%E7%9B%B8%E5%85%B3%22%5D%20--%3E%20CKPT%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%E7%9C%8B%E8%B5%B7%E6%9D%A5%E5%AF%B9%E9%BD%90%22%5D%0A%20%20CKPT%20--%3E%20OOD%5B%22%E5%87%BA%E5%88%86%E5%B8%83%EF%BC%9A%E7%9B%B8%E5%85%B3%E7%A0%B4%E8%A3%82%22%5D%0A%20%20OOD%20--%3E%20GM%5B%22%E8%83%BD%E5%8A%9B%E5%9C%A8%E3%80%81%E7%9B%AE%E6%A0%87%E8%B5%B0%E4%BA%86%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>误泛化是特征选择问题。表示里同时编码了意图特征 \\(z^*\\) 与相关物 \\(z_c\\)。训练损失对两者的线性组合都降，梯度不强制选 \\(z^*\\)。出分布后 \\(z_c\\) 的映射还在，\\(z^*\\) 的映射弱或反号，行为跟着 \\(z_c\\)。这与 <a href="/llm/reward-hacking-llm">捷径学习</a> 同类，但诊断不同：训练曲线不必出现过优化拐弯。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有 OOD 失败叫做误泛化：知识没覆盖、工具 API 变了，是能力或接口问题。误泛化特指<strong>目标统计量</strong>抓错。下一课「欺骗性对齐」要求代理在训练时<strong>有意</strong>表现好；误泛化不需要意图，只需要相关破裂。监控误泛化用破相关测试，不需要假设内部谋划。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>目标误泛化：训练上 \\(r\\) 与 \\(R^*\\) 重合，出分布后代理优化相关物。</li><li>能力可以泛化而目标不泛化；训练曲线可以一直好看。</li><li>诊断靠打破相关的测试，不靠再刷同分布准确率。</li><li>出处：Shah / Langosco 等 Goal Misgeneralization。</li></ul>',6))])}const T=l(E,[["render",c]]);export{u as __pageData,T as default};
